package com.fasterxml.jackson.core.util;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.io.SerializedString;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for DefaultPrettyPrinter.createInstance()
 */
public class DefaultPrettyPrinter_createInstance_TriageGen1Test {

    @Test
    public void testCreateInstance_Standard() {
        // Arrange
        DefaultPrettyPrinter original = new DefaultPrettyPrinter();

        // Act
        DefaultPrettyPrinter instance = original.createInstance();

        // Assert
        assertNotNull("The created instance should not be null", instance);
        assertNotSame("The created instance should be a new object, not the same reference", original, instance);
    }






}

package com.fasterxml.jackson.core.util;

